const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const $=s=>document.querySelector(s),money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='motorflu-demo-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}state=state||{clients:[{id:'c1',name:'Joãozinho Autopeças',legal:'Joãozinho Autopeças — exemplo',cnpj:'',city:'Juiz de Fora / MG',address:'Rua de exemplo, 100 — Centro',contact:'João',phone:'',email:'',rep:'Márcio'}],reps:[{name:'Márcio',email:'',active:true}],orders:[],prices:{},cart:{client:'c1',items:[],payment:'A combinar',notes:''}};
let role='rep',user=null,page='dashboard',search='',category='',filter='';const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Não foi possível salvar. Verifique o espaço do navegador.')}};const price=p=>state.prices[p.id]??p.price;const product=id=>PRODUCTS.find(p=>p.id===id);const sum=items=>items.reduce((a,i)=>a+i.qty*i.price,0);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
const status=s=>`<span class="status ${['Confirmado','Em preparação','Concluído'].includes(s)?'ok':['Não aprovado','Cancelado'].includes(s)?'no':s==='Rascunho'?'draft':''}">${esc(statusName(s))}</span>`;const visibleOrders=()=>state.orders.filter(o=>role==='gestor'||o.rep===user);const visibleClients=()=>state.clients.filter(c=>role==='gestor'||c.rep===user);const navIcon={"dashboard": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/></svg>", "catalog": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m12 3 9 5-9 5-9-5 9-5Z\"/><path d=\"M3 8v9l9 5 9-5V8M12 13v9M7.5 5.5l9 5\"/></svg>", "clients": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"9\" cy=\"8\" r=\"4\"/><path d=\"M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8M22 21v-3a7 7 0 0 0-3-5\"/></svg>", "orders": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"5\" y=\"4\" width=\"14\" height=\"18\" rx=\"2\"/><path d=\"M9 2h6v4H9zM9 11h6M9 16h6\"/></svg>", "reps": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"7\" r=\"4\"/><path d=\"M4 22v-3a8 8 0 0 1 16 0v3M9 14l3 4 3-4\"/></svg>"};const navs=[['dashboard','◫','Visão geral'],['catalog','▦','Catálogo'],['clients','♧','Clientes'],['orders','▤','Pedidos']];
function login(){user=null;$('#app').innerHTML=`<div class="login"><section class="login-brand"><div><img class="brand" src="data:image/png;base64," alt="Motorflu Automotive"><div class="brand-caption">CENTRAL DE PEDIDOS</div></div><div><div class="eyebrow">Sua próxima venda começa aqui</div><h1>Mais agilidade.<br>Mais <span>movimento.</span></h1><p>Seu catálogo, seus clientes e seus pedidos. Uma operação conectada, do representante à gestão.</p></div><footer class="muted">MOTORFLU AUTOMOTIVE · PORTAL COMERCIAL</footer></section><section class="login-form"><div class="login-card"><span class="eyebrow">Bem-vindo à Motorflu</span><h1>Acesse sua área.</h1><p class="muted">Escolha um perfil para experimentar o aplicativo.</p><div class="rolepick"><button data-role="rep" class="${role==='rep'?'selected':''}"><span class="role-icon">${navIcon.reps}</span>Demonstração — Representante de vendas<small>Clientes, catálogo e pedidos</small></button><button data-role="gestor" class="${role==='gestor'?'selected':''}"><span class="role-icon">${navIcon.dashboard}</span>Demonstração — Gestor<small>Aprovação e visão da operação</small></button></div>${role==='rep'?`<label>Representante de exemplo<select id="demo-name" class="wide">${state.reps.filter(r=>r.active).map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label>`:'<p class="note">Você entrará como Gestor Motorflu nesta demonstração.</p>'}<button class="primary wide" id="enter" style="margin-top:22px" ${role==='rep'&&!state.reps.some(r=>r.active)?'disabled':''}>Entrar na demonstração →</button><p class="note">Versão de teste, sem autenticação real. Os dados ficam apenas neste navegador. Preços ilustrativos; e-mails não são enviados.</p></div></section></div>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;login()});$('#enter').onclick=()=>{user=role==='gestor'?'Gestor Motorflu':$('#demo-name').value;page='dashboard';render()}}
function render(){const links=[...navs,['samples','','Amostras'],['policy','','Política comercial'],...(role==='gestor'?[['inventory','','Estoque'],['reps','♙','Representantes']]:[])];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><img class="brand" src="data:image/png;base64," alt="Motorflu"><div class="brand-caption">CENTRAL DE PEDIDOS</div><nav class="nav">${links.map(([id,icon,name])=>`<button data-nav="${id}" class="${page===id?'active':''}"><span class="ico" aria-hidden="true">${navIcon[id]||navIcon.catalog}</span><span class="nav-label">${id==='dashboard'?'Início':id==='reps'?'Equipe':name}</span></button>`).join('')}</nav><div class="sidefoot"><span class="signal"></span>Ambiente de demonstração<br><strong>Motorflu Automotive</strong><br>Vendas em movimento.</div></aside><main class="main"><header class="topbar"><span class="crumb">Central de Pedidos <span style="padding:0 12px">/</span> ${links.find(x=>x[0]===page)?.[2]||'Área comercial'}</span><img src="data:image/png;base64," class="mobilebrand" alt="Motorflu"><div class="profile"><span class="avatar">${esc(user[0])}</span><span>${esc(user)}<small>${role==='gestor'?'Gestor':'Representante de vendas'}</small></span><button class="quiet" id="logout">Sair</button></div></header><div class="content"><div class="demo"><span>DEMONSTRAÇÃO · Preços fictícios e dados salvos neste navegador.</span><span>v0.4</span></div><div id="view"></div></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$('#logout').onclick=login;({dashboard,catalog,clients,orders,cart,reps,samples,policy,inventory,approvals,profilePage}[page]||dashboard)();decorateShell()}
function go(p){page=p;search='';category='';filter='';render();window.scrollTo(0,0)}
function heading(ey,title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}function orderTable(list){return list.length?`<div class="tablewrap mobile-cards"><table><thead><tr><th>Pedido / data</th><th>Cliente</th><th>Representante</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>#${esc(o.number)}</strong><small>${new Date(o.date).toLocaleString('pt-BR')}</small></td><td>${esc(o.client.name)}<small>${esc(o.client.code||clientCode(o.client.id))}</small></td><td>${esc(fullName(repByName(o.rep))||o.rep)}<small>${esc(o.repCode||repByName(o.rep)?.code||'')}</small></td><td><strong>${money(sum(o.items))}</strong></td><td>${status(o.status)}</td><td><button class="textbtn" data-order="${o.id}">Ver pedido →</button></td></tr>`).join('')}</tbody></table></div>`:(role==='gestor'?'<div class="empty">Nenhum pedido recebido ainda.</div>':'<div class="empty">Nenhum pedido por aqui ainda.<br><p>Abra o catálogo e monte seu primeiro pedido.</p><button class="primary" onclick="go(\'catalog\')">Explorar catálogo</button></div>')}function labelCards(){document.querySelectorAll('.mobile-cards table').forEach(t=>{const labels=[...t.querySelectorAll('th')].map(h=>h.textContent);t.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.dataset.label=labels[i]||'Ações'))})}function wireOrders(){labelCards();document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>detail(b.dataset.order))}
function dashboard(){const os=visibleOrders(),confirmed=os.filter(o=>o.status==='Confirmado');$('#view').innerHTML=heading('Painel comercial',`Olá, ${esc(role==='gestor'?'Gestor':user.split(' ')[0])}.`,role==='gestor'?'Acompanhe sua operação e mantenha os pedidos em movimento.':'Tudo pronto para a sua próxima venda.',`<button class="primary" onclick="go('catalog')">＋ Novo pedido</button>`)+`<div class="stats"><div class="stat"><span class="label">Vendas confirmadas <span>↗</span></span><strong>${money(confirmed.reduce((a,o)=>a+sum(o.items),0))}</strong><small>Total dos pedidos aprovados</small></div><div class="stat"><span class="label">Pedidos enviados <span>▤</span></span><strong>${os.length.toString().padStart(2,'0')}</strong><small>Registrados nesta demonstração</small></div><div class="stat"><span class="label">Aguardando aprovação <span>◷</span></span><strong>${os.filter(o=>o.status==='Aguardando aprovação').length.toString().padStart(2,'0')}</strong><small>Em análise pela gestão</small></div><div class="stat"><span class="label">Clientes cadastrados <span>♧</span></span><strong>${visibleClients().length.toString().padStart(2,'0')}</strong><small>${role==='gestor'?'Na carteira da equipe':'Na sua carteira'}</small></div></div><div class="dashgrid"><section class="panel"><div class="panel-head"><h2>Pedidos recentes</h2><button class="textbtn" onclick="go('orders')">Ver todos →</button></div>${orderTable(os.slice().reverse().slice(0,5))}</section><aside><section class="panel"><div class="panel-head"><h2>Acesso rápido</h2></div><div class="panel-body quick"><button onclick="go('catalog')">Explorar catálogo <span>↗</span></button><button onclick="clientForm()">Cadastrar cliente <span>＋</span></button><button onclick="go('cart')">Continuar pedido <span>→</span></button></div></section><div class="panel" style="margin-top:20px"><div class="panel-body"><span class="eyebrow">Do catálogo ao pedido</span><h3 style="margin-top:14px">Feito para vender melhor.</h3><p class="note">Escolha o cliente, adicione produtos e envie para aprovação. O gestor acompanha tudo por aqui.</p><span class="tag">${PRODUCTS.length} produtos no catálogo</span></div></div></aside></div>`;wireOrders()}
function catalog(){if(!$('#product-grid')){$('#view').innerHTML=heading(role==='gestor'?'Gestão comercial':'Linha completa Motorflu',role==='gestor'?'Gerenciar catálogo.':'Catálogo de produtos.',role==='gestor'?'Edite fotos, preços, estoque, descontos e amostras de cada produto.':'Fotos e informações do catálogo. Preços exclusivamente ilustrativos.')+`<div class="toolbar"><input id="find" type="search" placeholder="Buscar por produto ou aplicação" aria-label="Buscar produto"><select id="cat" aria-label="Linha"><option value="">Todas as linhas</option>${[...new Set(PRODUCTS.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><p class="note" id="count"></p><div class="catalog" id="product-grid"></div><div id="cartbar"></div>`;$('#find').oninput=e=>{search=e.target.value;catalog()};$('#cat').onchange=e=>{category=e.target.value;catalog()}}
const list=PRODUCTS.filter(p=>(!category||p.category===category)&&`${p.name} ${p.summary} ${p.category}`.toLowerCase().includes(search.toLowerCase()));$('#count').textContent=`${list.length} produtos encontrados`;
$('#product-grid').innerHTML=list.map(p=>`<article class="product"><div class="photo"><img loading="lazy" src="${photo(p.id)}" alt="${esc(p.name)}"></div><div class="product-info"><span class="category">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.summary)}<br>${esc(p.pack)}</p><button class="textbtn" data-product="${p.id}" style="margin:0;justify-content:flex-start">Informações do produto</button><div class="price">${money(variantPrice(p,variants(p)[0]))}</div>${promotionLabel(p)}<small class="muted" style="font-size:9px">Preço de demonstração</small>${role==='gestor'?`<button class="primary" data-price="${p.id}">Editar produto</button>`:''}<button data-add="${p.id}">＋ Adicionar ao pedido</button>${sampleAllowed(p.id)?`<button class="sample-button" data-sample="${p.id}">Solicitar amostra</button>`:'<p class="note">Amostra indisponível</p>'}</div></article>`).join('')||'<div class="empty">Nenhum produto encontrado.</div>';document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>chooseItem(b.dataset.add));document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>productDetail(b.dataset.product));document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>chooseItem(b.dataset.sample,true));document.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>editPrice(b.dataset.price));const n=state.cart.items.reduce((a,i)=>a+i.qty,0);$('#cartbar').innerHTML=n?`<div class="cartbar"><div><strong>${n} itens no pedido</strong><br><small>${money(sum(state.cart.items))} · preços de teste</small></div><button class="primary" onclick="go('cart')">Revisar pedido →</button></div>`:''}
function add(id){const p=product(id),i=state.cart.items.find(i=>i.id===id);if(i)i.qty++;else state.cart.items.push({id,name:p.name,pack:p.pack,price:price(p),qty:1});save();toast(p.name+' adicionado ao pedido')}
function modal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="quiet" onclick="document.querySelector('#modal').close()" aria-label="Fechar">✕</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function productDetail(id){const p=product(id);modal(esc(p.name),`<div class="detail-grid"><div class="photo" style="height:280px"><img src="${photo(p.id)}" alt="${esc(p.name)}"></div><div><span class="eyebrow">${esc(p.category)}</span><p>${esc(p.description)}</p><p>${esc(p.pack)}</p><strong>${money(variantPrice(p,variants(p)[0]))}</strong>${promotionLabel(p)}<p class="note">Preço ilustrativo.</p><button class="primary" id="add-detail">Adicionar ao pedido</button></div></div>`);$('#add-detail').onclick=()=>chooseItem(id)}
function editPrice(id){const p=product(id);modal('Preço de demonstração',`<form id="price-form"><label>${esc(p.name)}<input name="price" type="number" step="0.01" min="0.01" required value="${price(p)}"></label><p class="note">Vale para novos itens adicionados. Pedidos existentes mantêm o preço registrado.</p><button class="primary">Salvar preço</button></form>`);$('#price-form').onsubmit=e=>{e.preventDefault();state.prices[id]=Number(new FormData(e.target).get('price'));save();$('#modal').close();catalog()}}
function clients(){$('#view').innerHTML=heading('Relacionamentos que movem vendas','Seus clientes.','Cadastre os dados da loja e facilite os próximos pedidos.',`<button class="primary" onclick="clientForm()">＋ Novo cliente</button>`)+`<div class="toolbar"><input id="find-client" type="search" placeholder="Buscar por nome, CNPJ ou cidade" aria-label="Buscar cliente"></div><section class="panel" id="client-table"></section>`;$('#find-client').oninput=e=>drawClients(e.target.value);drawClients('')}
function drawClients(q){const list=visibleClients().filter(c=>(c.name+c.cnpj+c.city+c.code).toLowerCase().includes(q.toLowerCase()));$('#client-table').innerHTML=`<div class="tablewrap mobile-cards"><table><thead><tr><th>Cliente</th><th>CNPJ</th><th>Cidade</th><th>Representante</th><th>Ações</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.code)} · ${esc(c.contact)}</small></td><td>${esc(c.cnpj||'Exemplo — não informado')}</td><td>${esc(c.city)}</td><td>${esc(c.rep)}</td><td><button class="textbtn" data-client="${c.id}">Fazer pedido</button> <button class="quiet" data-editclient="${c.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">Nenhum cliente encontrado.</div>':''}`;labelCards();document.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>{state.cart.client=b.dataset.client;save();go('catalog')});document.querySelectorAll('[data-editclient]').forEach(b=>b.onclick=()=>clientForm(b.dataset.editclient))}
function clientForm(id,afterSave){const c=state.clients.find(c=>c.id===id)||{};const fields=[['name','Nome fantasia',true],['legal','Razão social',true],['cnpj','CNPJ',true],['contact','Responsável',true],['phone','WhatsApp / Telefone',true],['email','E-mail',false],['city','Cidade / UF',true],['address','Endereço completo',true]];modal(id?'Editar cliente':'Novo cliente',`<form id="client-form"><div class="formgrid">${fields.map(([n,l,r])=>`<label>${l}${r?' *':''}<input name="${n}" ${r?'required':''} ${n==='email'?'type="email"':''} value="${esc(c[n]||'')}"></label>`).join('')}${role==='gestor'?`<label>Representante<select name="rep" class="wide">${state.reps.filter(r=>r.active).map(r=>`<option ${c.rep===fullName(r)?'selected':''}>${esc(fullName(r))}</option>`).join('')}</select></label>`:''}</div><div class="modal-actions"><button type="button" onclick="document.querySelector('#modal').close()">Cancelar</button><button class="primary">Salvar cliente</button></div></form>`);$('#client-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.rep=role==='gestor'?data.rep:user;if(Object.values(data).some(v=>!v.trim()&&['name','legal','contact','city','address'].some(k=>data[k]===v))){toast('Preencha os campos obrigatórios.');return}if(!validPhone(data.phone)){toast('Informe um telefone com DDD válido.');return}if(!validCnpj(data.cnpj)){toast('Informe um CNPJ válido.');return}data.code=c.code||nextCode('CLI',state.clients);data.id=id||uid();if(id)state.clients[state.clients.findIndex(c=>c.id===id)]=data;else state.clients.push(data);state.cart.client=data.id;save();$('#modal').close();render();toast('Cliente salvo nesta demonstração');if(afterSave)afterSave(data)};}
function cart(){const c=state.cart,cs=visibleClients();if(!cs.some(x=>x.id===c.client))c.client=cs[0]?.id||'';$('#view').innerHTML=heading('Novo pedido','Revise antes de enviar.','Confira o cliente, as quantidades e a condição de pagamento.',`<button onclick="go('catalog')">＋ Adicionar produtos</button>`)+`<div class="order-layout"><section class="panel"><div class="panel-head"><h2>Itens do pedido</h2><span class="tag">${c.items.length} produtos</span></div>${c.items.length?`<div class="tablewrap"><table><thead><tr><th>Produto</th><th>Preço unit.</th><th>Qtd.</th><th>Subtotal</th><th></th></tr></thead><tbody>${c.items.map((i,n)=>`<tr><td><img class="itemphoto" src="${photo(i.id)}" alt=""><strong>${esc(i.name)}</strong><small>${esc(i.pack)}</small></td><td>${money(i.price)}</td><td><input class="qty" aria-label="Quantidade ${esc(i.name)}" data-qty="${n}" type="number" min="1" max="9999" step="1" value="${i.qty}"></td><td>${money(i.price*i.qty)}</td><td><button class="quiet" data-remove="${n}" aria-label="Remover ${esc(i.name)}">✕</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Seu pedido ainda está vazio.</div>'}</section><section class="panel"><div class="panel-head"><h2>Resumo do pedido</h2></div><div class="panel-body"><label>Cliente<select class="wide" id="cart-client"><option value="">Selecione um cliente</option>${cs.map(x=>`<option value="${x.id}" ${x.id===c.client?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="textbtn" style="margin:8px 0 18px" onclick="clientForm()">＋ Cadastrar novo cliente</button><label>Condição de pagamento<select class="wide" id="payment">${paymentOptions().map(x=>`<option ${x===c.payment?'selected':''}>${x}</option>`).join('')}</select></label><label style="margin-top:18px">Observações<textarea id="notes" rows="3" placeholder="Entrega, frete ou orientações">${esc(c.notes)}</textarea></label><div class="totalrow"><span>Frete</span><span>${esc(state.policy.freight)}</span></div><p class="note">${esc(state.policy.discount)}</p><div class="totalrow big"><span>Total dos itens</span><span>${money(sum(c.items))}</span></div><button class="primary wide" id="submit-order" ${!c.items.length||!cs.length?'disabled':''}>Enviar para aprovação →</button><p class="note">Neste teste, o envio registra o pedido no navegador. Não envia e-mail nem realiza uma venda real.</p></div></section></div>`;$('#cart-client').onchange=e=>{c.client=e.target.value;save()};$('#payment').onchange=e=>{c.payment=e.target.value;save()};$('#notes').oninput=e=>{c.notes=e.target.value;save()};document.querySelectorAll('[data-qty]').forEach(b=>b.onchange=()=>{if(!b.checkValidity()||!Number.isInteger(Number(b.value))){toast('Informe uma quantidade inteira entre 1 e 9999.');b.value=c.items[b.dataset.qty].qty;return}c.items[b.dataset.qty].qty=Number(b.value);save();cart()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{c.items.splice(Number(b.dataset.remove),1);save();cart()});$('#submit-order').onclick=()=>{const client=cs.find(x=>x.id===c.client);if(!client){toast('Selecione o cliente.');return}if(!validPhone(client.phone)){toast('Informe o WhatsApp ou telefone do cliente antes de enviar.');clientForm(client.id);return}if(!checkItems(c.items))return;const o={id:uid(),number:String(state.orders.length+1).padStart(6,'0'),date:new Date().toISOString(),rep:role==='gestor'?client.rep:user,client:structuredClone(client),items:structuredClone(c.items),payment:c.payment,commercial:structuredClone(state.policy),notes:c.notes,status:'Aguardando aprovação',history:[{status:'Aguardando aprovação',date:new Date().toISOString(),by:user}]};o.client.code=client.code;o.repCode=repByName(o.rep)?.code||'';queueWhatsApp(o,'received');state.orders.push(o);state.cart={client:c.client,items:[],payment:'A combinar',notes:''};save();go('orders');detail(o.id);toast('Pedido de teste registrado. E-mail não enviado.')}}
function orders(){$('#view').innerHTML=heading('Da venda à confirmação','Pedidos.','Consulte os detalhes, acompanhe o status e salve uma cópia.',`<button class="primary" onclick="go('catalog')">＋ Novo pedido</button>`)+`<div class="toolbar"><input id="find-order" placeholder="Buscar por cliente, representante ou número" aria-label="Buscar pedido"><select id="order-status" aria-label="Status"><option value="">Todos os status</option><option>Aguardando aprovação</option><option>Confirmado</option><option>Não aprovado</option></select></div><section class="panel" id="orders-table"></section>`;const draw=()=>{const q=$('#find-order').value.toLowerCase(),s=$('#order-status').value;$('#orders-table').innerHTML=orderTable(visibleOrders().filter(o=>(!s||s===o.status)&&(o.client.name+o.rep+o.number).toLowerCase().includes(q)).reverse());wireOrders()};$('#find-order').oninput=draw;$('#order-status').onchange=draw;draw()}
function detail(id){const o=visibleOrders().find(x=>x.id===id);if(!o)return;modal(`Pedido #${o.number}`,`<div class="printhead"><img src="data:image/png;base64," alt="Motorflu"></div><div style="display:flex;justify-content:space-between;align-items:center">${status(o.status)}<span class="note">${new Date(o.date).toLocaleString('pt-BR')}</span></div><div class="detail-grid"><div><span class="eyebrow">Cliente</span><h3 style="margin-top:9px">${esc(o.client.name)}</h3><p>${esc(o.client.legal)}<br>CNPJ: ${esc(o.client.cnpj||'Não informado — exemplo')}<br>${esc(o.client.address)}<br>${esc(o.client.city)}<br>${esc(o.client.contact)} · ${esc(o.client.phone)}<br>${esc(o.client.email)}</p></div><div><span class="eyebrow">Representante</span><h3 style="margin-top:9px">${esc(fullName(repByName(o.rep))||o.rep)}</h3><p>${esc(o.repCode||repByName(o.rep)?.code||'')}</p><p>Pagamento: ${esc(o.payment)}<br>Frete: ${esc(o.commercial?.freight||'A combinar')}</p><p>Pedido demonstrativo. Preços fictícios.<br>Não é documento fiscal.</p></div></div><div class="tablewrap"><table><thead><tr><th>Produto / embalagem</th><th>Qtd.</th><th>Preço</th><th>Subtotal</th></tr></thead><tbody>${o.items.map(i=>`<tr><td><img class="itemphoto" src="${photo(i.id)}" alt="${esc(i.name)}"><strong>${esc(i.name)}</strong><small>${esc(i.pack)}</small></td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</tbody></table></div><div class="totalrow big" style="margin-top:20px"><span>Total dos itens</span><span>${money(sum(o.items))}</span></div>${o.notes?`<p class="note">Observações: ${esc(o.notes)}</p>`:''}${o.reason?`<p class="note">${o.status==='Cancelado'?'Motivo do cancelamento':'Motivo da não aprovação'}: ${esc(o.reason)}</p>`:''}<p class="note">Status na emissão desta cópia: ${esc(statusName(o.status))}. Consulte o aplicativo para acompanhar atualizações.</p><div class="noprint"><h3 style="margin-top:25px">Histórico do pedido</h3>${(o.history||[]).map(h=>`<p class="note">${esc(statusName(h.status))} · ${esc(h.by)} · ${new Date(h.date).toLocaleString('pt-BR')}${h.note?'<br>'+esc(h.note):''}</p>`).join('')}<p class="note">Envio de e-mail: não configurado nesta versão.</p></div><div class="modal-actions"><button id="print-order">Imprimir / salvar PDF</button>${role==='gestor'&&o.status==='Aguardando aprovação'?'<button id="reject-order">Não aprovar</button><button class="primary" id="approve-order">Aprovar pedido</button>':''}</div>`);$('#print-order').onclick=async()=>{await Promise.all([...$('#modal').querySelectorAll('img')].map(i=>i.decode().catch(()=>{})));window.print()};enhanceOrderDetail(o);if($('#approve-order'))$('#approve-order').onclick=()=>changeStatus(o,'Confirmado');if($('#reject-order'))$('#reject-order').onclick=()=>{modal('Não aprovar pedido',`<form id="reject-form"><label>Motivo<textarea name="reason" rows="3" required></textarea></label><div class="modal-actions"><button type="button" id="back-order">Voltar</button><button class="primary">Registrar não aprovação</button></div></form>`);$('#back-order').onclick=()=>detail(id);$('#reject-form').onsubmit=e=>{e.preventDefault();const reason=new FormData(e.target).get('reason').trim();if(!reason)return;o.reason=reason;changeStatus(o,'Não aprovado')}}}
function changeStatus(o,s){if(role!=='gestor'||o.status!=='Aguardando aprovação')return;if(s==='Confirmado'&&!consumeStock(o.items))return;o.status=s;o.history.push({status:s,date:new Date().toISOString(),by:user});save();render();detail(o.id);toast('Status atualizado nesta demonstração')}
function reps(){if(role!=='gestor')return;$('#view').innerHTML=heading('Gestão da equipe','Representantes.','Gerencie os perfis de exemplo disponíveis para teste.',`<button class="primary" onclick="repForm()">＋ Novo representante</button>`)+`<section class="panel"><div class="tablewrap mobile-cards"><table><thead><tr><th>Representante</th><th>Contato</th><th>Pedidos</th><th>Situação</th><th></th></tr></thead><tbody>${state.reps.map((r,n)=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.email||'Não informado')}</td><td>${state.orders.filter(o=>o.rep===r.name).length}</td><td>${status(r.active?'Confirmado':'Não aprovado')}</td><td><button class="textbtn" data-toggle="${n}">${r.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p class="note">Perfis locais de demonstração. Convites, senhas e permissões reais serão configurados na etapa de integração.</p></div></section>`;labelCards();document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{state.reps[b.dataset.toggle].active=!state.reps[b.dataset.toggle].active;save();reps()})}
function repForm(){modal('Novo representante',`<form id="rep-form"><div class="formgrid"><label>Nome *<input name="name" required></label><label>E-mail<input name="email" type="email"></label></div><div class="modal-actions"><button class="primary">Cadastrar para teste</button></div></form>`);$('#rep-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name||state.reps.some(r=>r.name.toLowerCase()===d.name.toLowerCase())){toast('Informe um nome diferente dos já cadastrados.');return}state.reps.push({...d,active:true});save();$('#modal').close();reps()}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
